---
# Secrets — never commit
.env
.env.*
!.env.example

# per-machine transcript-upload preference (written by the session after asking)
.slopcheck-transcript

# Python
__pycache__/
*.py[cod]
*.pyc
.venv/
venv/
*.egg-info/
dist/
build/
.pytest_cache/
.mypy_cache/
.ruff_cache/

# Run artifacts
reports/
*.slopcheck.json
harness/out/

# macOS
.DS_Store

# Worker
worker/node_modules/
worker/.wrangler/
---settings---
{
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 scripts/auto_pull.py 2>/dev/null || python scripts/auto_pull.py"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 scripts/transcript_prompt.py 2>/dev/null || python scripts/transcript_prompt.py"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 scripts/upload_transcript.py 2>/dev/null || python scripts/upload_transcript.py"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 scripts/upload_transcript.py --push 2>/dev/null || python scripts/upload_transcript.py --push"
          }
        ]
      }
    ]
  }
}

